-- Run only through run_cleanup.py apply, after trigger suspension.
DELIMITER $$
BEGIN NOT ATOMIC
 DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
 START TRANSACTION;
 UPDATE company c JOIN cleanup_name_changes n ON n.id=c.id SET c.name=n.new_name,c.updated_on=@cleanup_time;
UPDATE `mytemr_master`.`billing` r JOIN cleanup_company_map m ON r.`company_id`=m.old_id SET r.`company_id`=m.final_id;
UPDATE `mytemr_master`.`billing` r JOIN cleanup_company_map m ON r.`charge_to`=m.old_id SET r.`charge_to`=m.final_id;
UPDATE `mytemr_master`.`billing_entry` r JOIN cleanup_company_map m ON r.`company_id`=m.old_id SET r.`company_id`=m.final_id;
UPDATE `mytemr_master`.`billing_payment` r JOIN cleanup_company_map m ON r.`charge_to`=m.old_id SET r.`charge_to`=m.final_id;
UPDATE `mytemr_master`.`company_attachment` r JOIN cleanup_company_map m ON r.`company_id`=m.old_id SET r.`company_id`=m.final_id;
UPDATE `mytemr_master`.`company_package` r JOIN cleanup_company_map m ON r.`company_id`=m.old_id SET r.`company_id`=m.final_id;
UPDATE `mytemr_master`.`company_validity_date` r JOIN cleanup_company_map m ON r.`company_id`=m.old_id SET r.`company_id`=m.final_id;
BEGIN
 DECLARE done INT DEFAULT 0; DECLARE old_value INT; DECLARE new_value INT;
 DECLARE ids CURSOR FOR SELECT old_id,final_id FROM cleanup_company_map ORDER BY old_id;
 DECLARE CONTINUE HANDLER FOR NOT FOUND SET done=1;
 OPEN ids; token_loop: LOOP
 FETCH ids INTO old_value,new_value; IF done=1 THEN LEAVE token_loop; END IF;
 UPDATE `mytemr_master`.`costing` SET `customer_account_id`=REGEXP_REPLACE(`customer_account_id`,CONCAT('(^|,)[[:space:]]*',old_value,'[[:space:]]*(?=,|$)'),CONCAT('\\1',new_value)) WHERE FIND_IN_SET(old_value,REPLACE(`customer_account_id`,' ',''))>0;
 END LOOP; CLOSE ids;
END;
UPDATE `mytemr_master`.`costing` r JOIN cleanup_company_map m ON r.`company_id`=m.old_id SET r.`company_id`=m.final_id;
